.ds-button {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    gap: 6px;
    min-height: var(--ui-control-height, 44px);
    max-width: 100%;
    border: 1px solid var(--ui-border, #475569);
    border-radius: var(--ui-control-radius, 8px);
    padding: 8px 12px;
    background: var(--ui-surface, #0f172a);
    color: var(--ui-text, #e2e8f0);
    font-size: 14px;
    font-weight: 600;
    line-height: 1.4;
    text-align: center;
    text-decoration: none;
    white-space: normal;
    overflow-wrap: anywhere;
    cursor: pointer;
    transition:
      background-color 120ms ease-out,
      border-color 120ms ease-out,
      color 120ms ease-out;
  }
.ds-button:hover:not(:disabled) {
    border-color: var(--ui-muted, #a8b8cc);
    background: var(--ui-raised, #17243a);
  }
.ds-button:focus-visible {
    outline: var(--ui-focus, 2px solid #67e8f9);
    outline-offset: 3px;
  }
.ds-button:disabled {
    opacity: 0.5;
    cursor: not-allowed;
  }
.ds-button--primary {
    border-color: transparent;
    background: var(--ui-accent, #67e8f9);
    color: var(--ui-on-accent, #082f49);
  }
.ds-button--primary:hover:not(:disabled) {
    border-color: transparent;
    background: var(--ui-accent-hover, #a5f3fc);
  }

