  }
.ds-button--action[aria-pressed="true"] {
    border-color: var(--ui-accent, #67e8f9);
    background: var(--ui-selected, #12374a);
  }

.ds-input {
    width: 100%;
    min-width: 0;
    max-width: 100%;
    min-height: var(--ui-control-height, 44px);
    border: 1px solid var(--ui-border, #475569);
    border-radius: var(--ui-control-radius, 8px);
    padding: 10px 12px;
    background: var(--ui-page, #07101f);
    color: var(--ui-text, #e2e8f0);
    font-size: 14px;
    line-height: 1.5;
  }
.ds-input::placeholder {
    color: var(--ui-muted, #a8b8cc);
    opacity: 1;
  }
.ds-input:focus-visible {
    outline: var(--ui-focus, 2px solid #67e8f9);
    outline-offset: 2px;
  }
.ds-input[aria-invalid="true"] {
    border-color: var(--ui-danger, #fecaca);
  }
.ds-input:disabled {
    opacity: 0.6;
  }

.ds-surface {
    border: 1px solid var(--ui-divider, #29364d);
    border-radius: var(--ui-surface-radius, 12px);
    background: var(--ui-surface, #0f172a);
  }

.ds-workflow-steps {
    display: flex;
    flex-wrap: wrap;
    gap: 8px 24px;
    margin: 0;
    border-bottom: 1px solid var(--ui-divider, #29364d);
    padding: 0 0 16px;
    list-style: none;
    color: var(--ui-muted, #a8b8cc);
    font-size: 12px;
  }
.ds-workflow-steps li {
    display: flex;
    align-items: baseline;
    gap: 8px;
    min-width: 0;
    overflow-wrap: anywhere;
  }
.ds-workflow-steps [aria-current="step"] {
    color: var(--ui-accent-hover, #a5f3fc);
    font-weight: 700;
  }
.ds-workflow-steps span {
    font-variant-numeric: tabular-nums;
  }
